export const pageTitle = "OHRYA PRIVACY POLICY";
export const policyHtml = "\r\n        <!-- Page Title -->\r\n        <header class=\"page-title\">\r\n          <h2>OHRYA PRIVACY POLICY</h2>\r\n        </header>\r\n\r\n        <!-- Content -->\r\n        <div class=\"policy-content\">\r\n          <!-- Introduction -->\r\n          <section class=\"section\">\r\n            <h2>1. INTRODUCTION</h2>\r\n\r\n            <div class=\"content-block\">\r\n              <p>\r\n                1.1 OHRYA Foundation, Inc. (\"OHRYA,\" \"we,\" \"us,\" \"our\") operates\r\n                the OHRYA platform at\r\n                <a class=\"links\" href=\"http://www.ohrya.org/\" target=\"_blank\">\r\n                  www.ohrya.org\r\n                </a>\r\n                (the \"Platform\").\r\n              </p>\r\n\r\n              <p>\r\n                1.2 This Privacy Policy explains how we collect, use, disclose,\r\n                and protect your personal information when you use the Platform.\r\n              </p>\r\n              <p>\r\n                1.3 By using the Platform, you consent to the data practices\r\n                described in this Privacy Policy.\r\n              </p>\r\n              <p>\r\n                1.4 This Privacy Policy is incorporated into and subject to the\r\n                OHRYA Terms of Service.\r\n              </p>\r\n            </div>\r\n          </section>\r\n\r\n          <!-- INFORMATION WE COLLECT -->\r\n          <section class=\"section\">\r\n            <h2>2. INFORMATION WE COLLECT</h2>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>2.1 Information You Provide Directly</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Account Information: Full legal name, Email address,\r\n                    Password (encrypted), Phone number (optional), Mailing\r\n                    address\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Contribution Information: Payment card details (tokenized by\r\n                    processor; we do NOT store full card numbers), Billing\r\n                    address, Contribution amount and date, Campaign selection,\r\n                    Pledge or donation confirmation\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Voting & Advocacy Information: Nonprofit voting preferences,\r\n                    Social Impact Score (SIS) activity, Referral links and\r\n                    conversions, Social media connections (if you link\r\n                    accounts), Advocacy content you create or share\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Communications: Messages sent to\r\n                    <a class=\"links\" href=\"mailto:hello@ohrya.org\">\r\n                      hello@ohrya.org </a\r\n                    >, Support requests, Feedback and sign up responses,\r\n                    Newsletter subscriptions\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Alternative Method of Entry (AMOE): Information submitted\r\n                    via mail or web form for free participation\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>2.2 Information We Collect Automatically</h3>\r\n\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Usage Data: Pages viewed and features used, Time spent on\r\n                    Platform, Click patterns and navigation paths, Campaign\r\n                    pages visited, Referral sources (how you found OHRYA)\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Device & Technical Information: IP address, Browser type and\r\n                    version, Operating system, Device identifiers (mobile device\r\n                    ID, advertising ID), Screen resolution, Time zone and\r\n                    language settings\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Cookies & Tracking Technologies: Session cookies (essential\r\n                    for Platform function), Analytics cookies (Google Analytics,\r\n                    if used), Preference cookies (remember your settings), See\r\n                    Section 9 for detailed cookie information\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>2.3 Information from Third Parties</h3>\r\n\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Payment Processors (Stripe, PayPal, etc.): Transaction\r\n                    confirmations, Payment success/failure status,\r\n                    Processor-assigned transaction IDs, We do NOT receive your\r\n                    full payment card numbers\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Social Media Platforms: If you connect Facebook, Twitter,\r\n                    Instagram, or other accounts to track SIS, We receive:\r\n                    username, follower count, public post data, engagement\r\n                    metrics, We do NOT post on your behalf without explicit\r\n                    permission\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Data Verification Services: Email verification services (to\r\n                    prevent fraud), IP geolocation services (to verify\r\n                    eligibility), Identity verification (for high-value\r\n                    contributions, if required by law)\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <!-- HOW WE USE YOUR INFORMATION -->\r\n          <section class=\"section\">\r\n            <h2>3. HOW WE USE YOUR INFORMATION</h2>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>3.1 Core Platform Operations</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    To Process Contributions: Charge pledges or donations, Issue\r\n                    tax-deductible receipts, Process refunds (if campaign\r\n                    threshold not met), Maintain contribution records for IRS\r\n                    compliance\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    To Manage Campaigns: Display nonprofit options, Count and\r\n                    certify votes, Calculate Social Impact Scores (SIS),\r\n                    Determine Luminary recognition, Disburse grants to winning\r\n                    nonprofits\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    To Enable Advocacy: Track referral conversions, Measure\r\n                    social media engagement, Calculate SIS using FairFluence\r\n                    algorithm, Display leaderboards (anonymized or identified,\r\n                    per your settings)\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>3.2 Communications</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Transactional Emails (you CANNOT opt out): Contribution\r\n                    confirmations and tax receipts, Voting confirmations,\r\n                    Campaign results and grant disbursements, AMOE entry\r\n                    confirmations, Refund notifications, Account security alerts\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Marketing Emails (you CAN opt out): New campaign\r\n                    announcements, Campaign updates and milestones, SIS\r\n                    leaderboard updates, Luminary recognition announcements,\r\n                    Platform news and feature updates\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>3.3 Platform Improvement & Analytics</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Analyze usage patterns to improve Platform, Identify and fix\r\n                    technical issues, A/B test new features, Optimize campaign\r\n                    performance, Research user behavior and preferences\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>3.4 Legal & Security</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Compliance: Comply with IRS reporting requirements (Form\r\n                    990), Meet state charitable solicitation registration\r\n                    obligations, Respond to legal requests (subpoenas, court\r\n                    orders), Maintain records for audits\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Fraud Prevention & Security: Detect and prevent fraudulent\r\n                    contributions, Identify bot activity and SIS manipulation,\r\n                    Enforce Terms of Service, Protect Platform integrity,\r\n                    Monitor for unauthorized access\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <!-- BLOCKCHAIN TRANSPARENCY -->\r\n          <section class=\"section\">\r\n            <h2>4. BLOCKCHAIN TRANSPARENCY</h2>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>4.1 What We Publish to Algorand Blockchain</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    OHRYA publishes anonymized campaign data to the Algorand\r\n                    blockchain for public transparency: Published Data: Campaign\r\n                    ID and threshold amount, Total contributions (aggregate, not\r\n                    individual), Nonprofit vote tallies, Winning nonprofit name,\r\n                    Grant amount and disbursement date, SIS leaderboards\r\n                    (User-ID hashes only, NOT names)\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>4.2 What is NOT Published</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Never published to blockchain: Your full name or real\r\n                    identity, Email address or contact information, Individual\r\n                    contribution amounts, Payment card information, Physical\r\n                    address, Any personally identifiable information (PII)\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>4.3 Anonymization Method</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Blockchain data uses cryptographic hashes (e.g.,\r\n                    User-12abc3def456) instead of real names.\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Only you and OHRYA can link your User-ID hash to your real\r\n                    identity. The public cannot.\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>4.4 Blockchain Immutability</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Critical Notice: Once data is published to the Algorand\r\n                    blockchain, it cannot be modified or deleted.\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    This ensures: Permanent public record of campaign results,\r\n                    Protection against data manipulation, Verifiable\r\n                    transparency\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Implication for privacy rights: Blockchain data is NOT\r\n                    subject to deletion requests under GDPR \"right to be\r\n                    forgotten\" or similar laws, because:\r\n                  </p>\r\n                  <ol>\r\n                    <li>It contains no personal information (only hashes)</li>\r\n                    <li>\r\n                      Deletion is technically impossible (blockchain\r\n                      immutability)\r\n                    </li>\r\n                    <li>\r\n                      Public transparency serves legitimate public interest\r\n                    </li>\r\n                  </ol>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <!-- HOW WE SHARE YOUR INFORMATION -->\r\n          <section class=\"section\">\r\n            <h2>5. HOW WE SHARE YOUR INFORMATION</h2>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>5.1 We Do NOT Sell Your Data</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    OHRYA does not sell, rent, or trade your personal\r\n                    information to third parties for marketing purposes.\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>5.2 Sharing with Nonprofits</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    If your chosen nonprofit wins the campaign, we share with\r\n                    them: Your name, Contribution amount, Email address (if you\r\n                    consent), Date of contribution\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Purpose: So they can thank you, issue their own\r\n                    acknowledgment, and include you in their donor records.\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Your control: You may opt out of nonprofit data sharing\r\n                    during the contribution process.\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>5.3 Service Providers</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    We share information with trusted vendors who help us\r\n                    operate the Platform:\r\n                  </p>\r\n                  <p>\r\n                    Payment Processors (Stripe, PayPal, etc.): Name, email,\r\n                    payment details, They process payments on our behalf,\r\n                    Subject to their own privacy policies\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Cloud Hosting (AWS, Google Cloud, etc.): All Platform data\r\n                    stored on secure cloud servers, Subject to industry-standard\r\n                    security (encryption, access controls)\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Email Service Providers (SendGrid, Mailchimp, etc.): Email\r\n                    addresses, names, campaign preferences, To send\r\n                    transactional and marketing emails\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Analytics Providers (Google Analytics, etc.): Anonymized\r\n                    usage data, To measure Platform performance\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Blockchain Infrastructure (Algorand): Anonymized campaign\r\n                    data only, Published to public blockchain\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Identity Verification (if required for high-value\r\n                    contributions): Name, address, date of birth (as required by\r\n                    law), To comply with anti-money laundering (AML) regulations\r\n                  </p>\r\n                  <p>\r\n                    All service providers are contractually required to: Use\r\n                    data only for specified purposes, Maintain confidentiality\r\n                    and security, Not sell or misuse data\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>5.4 Legal Requirements</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    We may disclose your information to: Comply with legal\r\n                    obligations (tax reporting, IRS audits), Respond to\r\n                    subpoenas, court orders, or government requests, Investigate\r\n                    fraud or suspected illegal activity, Protect OHRYA's rights,\r\n                    property, or safety, Enforce our Terms of Service\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>5.5 Business Transfers</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    If OHRYA is involved in a merger, acquisition, asset sale,\r\n                    or bankruptcy: Your information may be transferred as part\r\n                    of that transaction, We will notify you via email and\r\n                    Platform notice, The acquiring entity will be bound by this\r\n                    Privacy Policy\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <!-- YOUR PRIVACY RIGHTS & CHOICES -->\r\n          <section class=\"section\">\r\n            <h2>6. YOUR PRIVACY RIGHTS & CHOICES</h2>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>6.1 Access Your Data</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    You may request a copy of all personal information we hold\r\n                    about you.\r\n                  </p>\r\n                  <p>\r\n                    How: Email\r\n                    <a class=\"links\" href=\"mailto:hello@ohrya.org\">\r\n                      hello@ohrya.org\r\n                    </a>\r\n                    with subject \"Data Access Request\"\r\n                  </p>\r\n                  <p>Response time: Within 30 days</p>\r\n                  <p>Format: Provided as PDF or CSV file</p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>6.2 Correct Your Data</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>You may update or correct inaccurate information.</p>\r\n                  <p>\r\n                    How: Log into your account and edit profile, OR email\r\n                    <a class=\"links\" href=\"mailto:hello@ohrya.org\"\r\n                      >hello@ohrya.org\r\n                    </a>\r\n                  </p>\r\n                  <p>\r\n                    Limitations: You cannot change contribution history (IRS\r\n                    records must be accurate)\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>6.3 Delete Your Data</h3>\r\n\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    You may request deletion of your account and personal\r\n                    information.\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    How: Email\r\n                    <a class=\"links\" href=\"mailto:hello@ohrya.org\">\r\n                      hello@ohrya.org\r\n                    </a>\r\n                    with subject \"Account Deletion Request\"\r\n                  </p>\r\n                  <p>\r\n                    What we delete: Account credentials, Contact information,\r\n                    Non-essential usage data\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    What we CANNOT delete: Contribution records (IRS requires\r\n                    7-year retention), Blockchain data (technically impossible\r\n                    to delete), Records required for legal compliance or dispute\r\n                    resolution\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Timeline: Account deactivated within 5 business days; full\r\n                    deletion within 30 days (except retained records)\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>6.4 Opt Out of Marketing Emails</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    How: Click \"Unsubscribe\" at the bottom of any marketing\r\n                    email, Log into your account → Settings → Email Preferences,\r\n                    Email\r\n                    <a class=\"links\" href=\"mailto:hello@ohrya.org\">\r\n                      hello@ohrya.org\r\n                    </a>\r\n                    with \"Unsubscribe\" request\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Effect: You will stop receiving marketing emails but will\r\n                    continue to receive transactional emails (receipts, voting\r\n                    confirmations, etc.)\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>6.5 Opt Out of Nonprofit Data Sharing</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    During the contribution process, you can check a box to opt\r\n                    out of having your information shared with the winning\r\n                    nonprofit.\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Effect: Nonprofit will not receive your name, email, or\r\n                    contribution details.\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Note: You will still receive a tax receipt from OHRYA\r\n                    Foundation.\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>6.6 Manage Cookies</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    See Section 9 for how to control cookies through your\r\n                    browser settings.\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <!-- DATA SECURITY -->\r\n          <section class=\"section\">\r\n            <h2>7. DATA SECURITY</h2>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>7.1 Security Measures We Use</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Encryption: TLS 1.3 encryption for all data in transit\r\n                    (HTTPS), AES-256 encryption for sensitive data at rest,\r\n                    Payment card data tokenized (we never see full card numbers)\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Access Controls: Multi-factor authentication for OHRYA\r\n                    staff, Role-based access (staff only see data they need),\r\n                    Regular access audits\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Infrastructure Security: Secure cloud hosting (AWS, Google\r\n                    Cloud), Firewall protection, Intrusion detection systems,\r\n                    Regular security updates and patches\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Monitoring: 24/7 automated security monitoring, Alert\r\n                    systems for suspicious activity, Regular penetration testing\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>7.2 Your Responsibilities</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    To keep your account secure: Use a strong, unique password,\r\n                    Do not share your password with anyone, Log out on shared\r\n                    devices, Enable two-factor authentication (if available),\r\n                    Report suspicious activity immediately to\r\n                    <a class=\"links\" href=\"mailto:hello@ohrya.org\">\r\n                      hello@ohrya.org\r\n                    </a>\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>7.3 No Guarantee of Absolute Security</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    While we implement industry-standard security, no system is\r\n                    100% secure.\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    We cannot guarantee: That unauthorized access will never\r\n                    occur, That data breaches are impossible, That third-party\r\n                    services (payment processors, cloud providers) are perfectly\r\n                    secure\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    In the event of a data breach, we will: Notify affected\r\n                    users within 72 hours (or as required by law), Report to\r\n                    relevant authorities (FTC, state AGs), Take immediate action\r\n                    to contain and remedy the breach\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <!-- DATA RETENTION -->\r\n          <section class=\"section\">\r\n            <h2>8. DATA RETENTION</h2>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>8.1 How Long We Keep Your Data</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Active Accounts: Retained for as long as your account is\r\n                    active\r\n                  </p>\r\n                  <p>\r\n                    After Account Deletion: Most data deleted within 30 days,\r\n                    Exceptions: see below\r\n                  </p>\r\n                  <p>\r\n                    Contribution Records: Retained for 7 years after\r\n                    contribution (IRS requirement), Includes: name, amount,\r\n                    date, campaign, tax receipt\r\n                  </p>\r\n                  <p>\r\n                    Legal & Compliance Records: Retained as required by law\r\n                    (tax, charitable solicitation, anti-fraud), Typical\r\n                    retention: 7 years\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Blockchain Data: Permanent (cannot be deleted due to\r\n                    blockchain immutability), Only anonymized data is published\r\n                    (see Section 4)\r\n                  </p>\r\n                  <p>\r\n                    Dispute Resolution: Records related to disputes, legal\r\n                    claims, or Terms violations retained until resolved\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>8.2 After Retention Period</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Once the required retention period expires: Data is securely\r\n                    deleted or anonymized, Backups are purged, Exceptions:\r\n                    blockchain data (permanent), aggregate anonymous statistics\r\n                    (may be retained indefinitely)\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <!-- COOKIES & TRACKING TECHNOLOGIES -->\r\n          <section class=\"section\">\r\n            <h2>9. COOKIES & TRACKING TECHNOLOGIES</h2>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>9.1 What Are Cookies?</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Cookies are small text files stored on your device by your\r\n                    browser. They help us recognize you, remember your\r\n                    preferences, and improve your experience.\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>9.2 Types of Cookies We Use</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Essential Cookies (cannot be disabled): Session management\r\n                    (keeps you logged in), Security (protects against CSRF\r\n                    attacks), Load balancing (distributes server load)\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Analytics Cookies (can be disabled): Google Analytics (if\r\n                    used), Tracks page views, bounce rates, user flows, Helps us\r\n                    improve Platform\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Preference Cookies (can be disabled): Remember your\r\n                    language, time zone, display settings, Improve your user\r\n                    experience\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Advertising Cookies (if we ever use ads): Currently NOT\r\n                    used, If used in future, we will update this Policy and\r\n                    request consent\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>9.3 How to Control Cookies</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Browser Settings: Most browsers let you refuse cookies or\r\n                    delete existing cookies, Chrome: Settings → Privacy &\r\n                    Security → Cookies, Safari: Preferences → Privacy → Cookies,\r\n                    Firefox: Options → Privacy & Security → Cookies\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Effect of Disabling Cookies: Platform may not function\r\n                    properly, You may need to re-enter login credentials,\r\n                    Preferences will not be saved\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Do Not Track (DNT): Some browsers offer \"Do Not Track\"\r\n                    signals, OHRYA currently does not respond to DNT signals, We\r\n                    treat all users' data the same regardless of DNT settings\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>9.4 Third-Party Cookies</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    When you use the Platform, third-party services (Google\r\n                    Analytics, payment processors) may set their own cookies.\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    We do not control third-party cookies. Please review their\r\n                    privacy policies: Google Analytics:<a\r\n                      class=\"links\"\r\n                      href=\"https://policies.google.com/privacy\"\r\n                      target=\"_blank\"\r\n                    >\r\n                      https://policies.google.com/privacy </a\r\n                    >, Stripe:<a\r\n                      class=\"links\"\r\n                      href=\"https://stripe.com/privacy\"\r\n                      target=\"_blank\"\r\n                    >\r\n                      https://stripe.com/privacy </a\r\n                    >, PayPal:<a\r\n                      class=\"links\"\r\n                      href=\"https://www.paypal.com/privacy\"\r\n                      target=\"_blank\"\r\n                    >\r\n                      https://www.paypal.com/privacy</a\r\n                    >\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <!-- CHILDREN’S PRIVACY -->\r\n          <section class=\"section\">\r\n            <h2>10. CHILDREN’S PRIVACY</h2>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>10.1 Age Restriction</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    The Platform is NOT intended for individuals under 18 years\r\n                    of age.\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>10.2 No Knowing Collection from Children</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    We do not knowingly collect personal information from\r\n                    children under 13.\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    If we discover we have collected information from a child\r\n                    under 13 without verifiable parental consent, we will delete\r\n                    that information immediately.\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>10.3 Parental Rights</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    If you believe your child has provided information to OHRYA\r\n                    without your consent: Contact us immediately at\r\n                    <a class=\"links\" href=\"mailto:hello@ohrya.org\">\r\n                      hello@ohrya.org </a\r\n                    >, We will verify the situation and delete the information\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <!-- CALIFORNIA PRIVACY RIGHTS (CCPA) -->\r\n          <section class=\"section\">\r\n            <h2>11. CALIFORNIA PRIVACY RIGHTS (CCPA)</h2>\r\n            <p>\r\n              If you are a California resident, you have additional rights under\r\n              the California Consumer Privacy Act (CCPA):\r\n            </p>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>11.1 Right to Know</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    You may request disclosure of: Categories of personal\r\n                    information collected, Specific pieces of personal\r\n                    information we hold, Sources of personal information,\r\n                    Purposes for collecting or sharing information, Categories\r\n                    of third parties with whom we share information\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>11.2 Right to Delete</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    You may request deletion of your personal information,\r\n                    subject to exceptions: Legal obligations (IRS 7-year\r\n                    retention), Fraud prevention and security, Blockchain\r\n                    immutability (see Section 4.4)\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>11.3 Right to Opt-Out of Sale</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    We do NOT sell personal information. This right does not\r\n                    apply to OHRYA.\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>11.4 Right to Non-Discrimination</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    We will not discriminate against you for exercising your\r\n                    CCPA rights: Same prices and services for all, No denial of\r\n                    goods or services, No different quality of service\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>11.5 How to Exercise Your Rights</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Contact us:<a class=\"links\" href=\"mailto:hello@ohrya.org\">\r\n                      hello@ohrya.org\r\n                    </a>\r\n                  </p>\r\n                  <p>Subject line: “CCPA Request”</p>\r\n                  <p>\r\n                    Include: Your name, email, specific request (access, delete,\r\n                    etc.)\r\n                  </p>\r\n                  <p>\r\n                    Verification: We will verify your identity before processing\r\n                    requests (to prevent fraud)\r\n                  </p>\r\n                  <p>\r\n                    Response time: Within 45 days (may extend 45 additional days\r\n                    if complex)\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>11.6 Authorized Agents</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    You may designate an authorized agent to make CCPA requests\r\n                    on your behalf.\r\n                  </p>\r\n                  <p>\r\n                    Requirements: Written authorization from you, Proof of\r\n                    agent’s identity, We may still require direct verification\r\n                    from you\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <!-- EUROPEAN UNION PRIVACY RIGHTS (GDPR) -->\r\n          <section class=\"section\">\r\n            <h2>12. EUROPEAN UNION PRIVACY RIGHTS (GDPR)</h2>\r\n            <p>\r\n              If you are in the European Union, European Economic Area, or\r\n              United Kingdom, you have rights under the General Data Protection\r\n              Regulation (GDPR):\r\n            </p>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>12.1 Legal Basis for Processing</h3>\r\n              <p>We process your personal data based on:</p>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Consent: You provided explicit consent (e.g., marketing\r\n                    emails)\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Contract: Processing is necessary to fulfill our services\r\n                    (contributions, voting, SIS)\r\n                  </p>\r\n                  <p>\r\n                    Legitimate Interests: Fraud prevention, Platform security\r\n                    and integrity, Analytics and improvement\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Legal Obligation: IRS reporting, Anti-money laundering\r\n                    compliance, Response to legal requests\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>12.2 Your GDPR Rights</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>Right to Access: Request a copy of your data</p>\r\n                </li>\r\n                <li>\r\n                  <p>Right to Rectification: Correct inaccurate data</p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Right to Erasure (\"Right to be Forgotten\"): Request\r\n                    deletion, subject to exceptions (IRS retention, blockchain\r\n                    immutability)\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Right to Restrict Processing: Limit how we use your data\r\n                    (while verifying accuracy, etc.)\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Right to Data Portability: Receive your data in\r\n                    machine-readable format (CSV, JSON)\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Right to Object: Object to processing based on legitimate\r\n                    interests, We will stop unless we have compelling legitimate\r\n                    grounds\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Right to Withdraw Consent: For consent-based processing\r\n                    (marketing emails), Does not affect past processing\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Right to Lodge a Complaint: With your local data protection\r\n                    authority (DPA)\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>12.3 How to Exercise Your Rights</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Contact:<a\r\n                      class=\"links\"\r\n                      href=\"mailto:hello@ohrya.org\"\r\n                      target=\"_blank\"\r\n                    >\r\n                      hello@ohrya.org\r\n                    </a>\r\n                  </p>\r\n                  <p>Subject: \"GDPR Request\"</p>\r\n                  <p>\r\n                    Include: Your name, email, specific right you wish to\r\n                    exercise\r\n                  </p>\r\n                  <p>Response time: Within 30 days</p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>12.4 Data Transfers</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    OHRYA is based in the United States. If you are in the\r\n                    EU/EEA/UK: Your data may be transferred to and processed in\r\n                    the U.S., U.S. privacy laws may differ from EU laws, By\r\n                    using the Platform, you consent to this transfer\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Safeguards: We use standard contractual clauses (SCCs) with\r\n                    service providers, We implement adequate security measures\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>12.5 Data Protection Officer</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    For GDPR-related inquiries, you may contact:\r\n                    <a class=\"links\" href=\"mailto:hello@ohrya.org\">\r\n                      hello@ohrya.org</a\r\n                    >\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <!-- INTERNATIONAL USERS & DATA TRANSFERS -->\r\n          <section class=\"section\">\r\n            <h2>13. INTERNATIONAL USERS & DATA TRANSFERS</h2>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>13.1 U.S.-Based Operations</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    OHRYA is headquartered in Florida, USA. All Platform\r\n                    operations and data processing occur in the United States.\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>13.2 Cross-Border Data Transfers</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    If you access the Platform from outside the United States:\r\n                    Your information will be transferred to, stored, and\r\n                    processed in the U.S., U.S. data protection laws may differ\r\n                    from your country’s laws, By using the Platform, you consent\r\n                    to this transfer\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>13.3 Adequate Protection</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    We implement appropriate safeguards for international data\r\n                    transfers: Standard contractual clauses (SCCs), Encryption\r\n                    and security measures, Compliance with applicable data\r\n                    protection laws\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <!-- THIRD-PARTY LINKS & SERVICES -->\r\n          <section class=\"section\">\r\n            <h2>14. THIRD-PARTY LINKS & SERVICES</h2>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>14.1 External Links</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    The Platform may contain links to third-party websites,\r\n                    services, or social media platforms.\r\n                  </p>\r\n                  <p>\r\n                    We are NOT responsible for: Content or practices of\r\n                    third-party sites, Privacy policies of external services,\r\n                    Security of third-party platforms\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    Recommendation: Review the privacy policies of any\r\n                    third-party sites you visit.\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>14.2 Social Media Integrations</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    If you connect social media accounts (Facebook, Twitter,\r\n                    Instagram) to track SIS: You authorize us to access certain\r\n                    public data (followers, posts, engagement), Subject to that\r\n                    platform's privacy policy and terms, You can disconnect\r\n                    social accounts at any time\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <!-- CHANGES TO THIS PRIVACY POLICY -->\r\n          <section class=\"section\">\r\n            <h2>15. CHANGES TO THIS PRIVACY POLICY</h2>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>15.1 Right to Modify</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    OHRYA reserves the right to update this Privacy Policy at\r\n                    any time.\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>15.2 Notice of Changes</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Material changes will be communicated via: Prominent notice\r\n                    on the Platform (banner or pop-up), Email notification to\r\n                    registered users, Updated \"Last Updated\" date at the top of\r\n                    this Policy\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>15.3 Acceptance of Changes</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Your continued use of the Platform after changes are posted\r\n                    constitutes acceptance of the revised Privacy Policy.\r\n                  </p>\r\n                </li>\r\n                <li>\r\n                  <p>\r\n                    If you do not agree to changes, you must stop using the\r\n                    Platform and may request account deletion.\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <h3>15.4 Version History</h3>\r\n              <ul>\r\n                <li>\r\n                  <p>\r\n                    Previous versions of this Privacy Policy may be requested by\r\n                    emailing\r\n                    <a class=\"links\" href=\"mailto:hello@ohrya.org\">\r\n                      hello@ohrya.org </a\r\n                    >.\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <!-- CONTACT US -->\r\n          <section class=\"section\">\r\n            <h2>16. CONTACT US</h2>\r\n\r\n            <div class=\"content-block\">\r\n              <p>\r\n                For questions, concerns, or requests regarding this Privacy\r\n                Policy or your personal information:\r\n              </p>\r\n              <ul>\r\n                <li>\r\n                  <p>OHRYA Foundation, Inc.</p>\r\n                  <p>401 E. Las Olas Blvd., Suite 130-319</p>\r\n                  <p>Fort Lauderdale, FL 33301</p>\r\n                  <p>\r\n                    <a class=\"links\" href=\"mailto:hello@ohrya.org\">\r\n                      hello@ohrya.org\r\n                    </a>\r\n                  </p>\r\n                  <p>\r\n                    <a class=\"links\" href=\"tel:+1 (954) 400-0687\"></a> +1 (954)\r\n                    400-0687\r\n                  </p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n\r\n            <div class=\"content-block\">\r\n              <p>For Specific Requests:</p>\r\n              <ul>\r\n                <li>\r\n                  <p>Data Access: Subject line \"Data Access Request\"</p>\r\n                  <p>Data Deletion: Subject line \"Account Deletion Request\"</p>\r\n                  <p>\r\n                    Opt-Out: Subject line \"Unsubscribe\" or click link in emails\r\n                  </p>\r\n                  <p>CCPA Requests: Subject line \"CCPA Request\"</p>\r\n                  <p>GDPR Requests: Subject line \"GDPR Request\"</p>\r\n                  <p>Security Issues: Subject line \"URGENT: Security Issue\"</p>\r\n                </li>\r\n              </ul>\r\n            </div>\r\n          </section>\r\n\r\n          <!-- EFFECTIVE DATE  -->\r\n          <section class=\"section\">\r\n            <h2>17. EFFECTIVE DATE</h2>\r\n            <ul>\r\n              <li>\r\n                <p>This Privacy Policy is effective as of February 24, 2026</p>\r\n              </li>\r\n              <li>\r\n                <p>\r\n                  By using the OHRYA Platform on or after this date, you\r\n                  acknowledge that you have read, understood, and agree to this\r\n                  Privacy Policy.\r\n                </p>\r\n              </li>\r\n            </ul>\r\n          </section>\r\n        </div>\r\n      ";
